<?php

namespace App\Content;

/** Writes resources/js/types/page-content.ts: the `content` prop of every editable page. */
class TypeScript
{
    public const PATH = 'resources/js/types/page-content.ts';

    public static function generate(): string
    {
        $out = [
            '// Generated by `php artisan page-content:types` from app/Content/Pages. Do not edit by hand.',
            '',
            '/** An image field: `alt` is empty for a decorative image. */',
            'export type ContentImage = { src: string; alt: string };',
            '/** A link field. */',
            'export type ContentLink = { label: string; url: string };',
            '/** A question from the help centre, or null when it is a draft or deleted. */',
            'export type ContentQuestion = { id: number; title: string } | null;',
            '/** A rich field: cleaned HTML; render it with <RichContent>. */',
            'export type ContentHtml = string;',
        ];
        $shared = [];
        foreach (PageContent::pages() as $key => $schema) {
            $name = self::typeName($key);
            $out[] = '';
            $out[] = "/** {$schema->title}".($schema->url ? " ({$schema->url})" : '').': app/Content/Pages/'.class_basename($schema).'.php */';
            $out[] = "export type $name = {";
            foreach ($schema->sections() as $section) {
                $out[] = "\t{$section->key}: {";
                foreach ($section->fields as $field) {
                    $out[] = "\t\t{$field->key}: ".self::type($field).';';
                }
                $out[] = "\t};";
            }
            $out[] = '};';
            if ($schema->shared) {
                $shared[$key] = $name;
            }
        }
        $out[] = '';
        $out[] = '/** The shared prop `siteContent`: parts shown on every page (PageSchema::$shared). */';
        $out[] = $shared ? 'export type SiteContent = {' : 'export type SiteContent = Record<string, never>;';
        if ($shared) {
            foreach ($shared as $key => $name) {
                $out[] = "\t$key: $name;";
            }
            $out[] = '};';
        }

        return implode("\n", $out)."\n";
    }

    public static function typeName(string $key): string
    {
        return str_replace(' ', '', ucwords(str_replace(['_', '-'], ' ', $key))).'Content';
    }

    private static function type(Field $field): string
    {
        return match ($field->type) {
            'text', 'textarea' => 'string',
            'rich' => 'ContentHtml',
            'select' => implode(' | ', array_map(fn ($value) => json_encode((string) $value), array_keys($field->options))),
            'link' => 'ContentLink',
            'image' => 'ContentImage',
            'faq' => 'ContentQuestion',
            'list' => '{ '.implode('; ', array_map(fn (Field $sub) => "{$sub->key}: ".self::type($sub), $field->fields)).' }[]',
        };
    }
}
